def _rag_detect_language(text: str) -> str:
    sample = str(text or "")
    latin = len(re.findall(r"[A-Za-z]", sample))
    cjk = len(re.findall(r"[\u4e00-\u9fff\u3040-\u30ff]", sample))
    if cjk > latin * 1.2 and cjk >= 8:
        return "zh"
    if latin > cjk * 1.5 and latin >= 12:
        return "en"
    if latin and cjk:
        return "mixed"
    if cjk:
        return "zh"
    if latin:
        return "en"
    return "unknown"

