def _rag_cjk_ngrams(seq: str, *, min_n: int = 2, max_n: int = 4, limit: int = 120) -> list[str]:
    text = re.sub(r"\s+", "", str(seq or ""))
    out: list[str] = []
    if len(text) < min_n:
        return out
    for n in range(min_n, max_n + 1):
        if len(out) >= limit:
            break
        for idx in range(0, max(0, len(text) - n + 1)):
            out.append(text[idx : idx + n])
            if len(out) >= limit:
                break
    return out

