def _rag_filter_entities(values: list[object], limit: int = 32) -> list[str]:
    out: list[str] = []
    seen: set[str] = set()
    for value in values or []:
        token = re.sub(r"\s+", " ", str(value or "").strip())
        if not token or not _rag_entity_allowed(token):
            continue
        key = token.lower()
        if key in seen:
            continue
        seen.add(key)
        out.append(token)
        if len(out) >= limit:
            break
    return out

